export interface Destination {
    readonly id: string;
    readonly label: string;
    readonly glyph?: string;
    readonly disabled?: boolean;
}

export interface TronNavigationViewProps {
    readonly items: readonly Destination[];
    readonly footerItems?: readonly Destination[];
    readonly selectedId: string | null;
    readonly paneMode?: "auto" | "expanded" | "compact" | "minimal";
    readonly paneOpen: boolean;
    readonly paneTitle?: string;
    readonly settingsVisible?: boolean;
    readonly onSelectionRequested: (id: string) => void;
    readonly onPaneOpenRequested: (open: boolean) => void;
    readonly onSettingsRequested?: () => void;
    readonly onNativeError?: (error: Error) => void;
    readonly style?: StyleProp<ViewStyle>;
}

declare class NavigationBindingOwner {
    private snapshot;
    private readonly changes;
    private readonly events;
    private attached;
    readonly getSnapshot: () => Snapshot;
    readonly subscribe: (listener: Listener) => (() => void);
    private requireLive;
    private update;
    readonly transport: WindowsNativeNavigationTransport;
    attach(token: object): () => void;
    emit(token: object, event: WindowsNativeNavigationEvent): void;
    dispose(): void;
}

interface Snapshot extends WindowsNavigationState {
    readonly disposed: boolean;
}

export interface WindowsNavigationBinding {
    readonly transport: WindowsNativeNavigationTransport;
    dispose(): void;
}

export interface WindowsNavigationHostProps {
    readonly binding: WindowsNavigationBinding;
    readonly style?: StyleProp<ViewStyle>;
    readonly onNativeError?: (error: Error) => void;
}

export interface WindowsDesktopTransport {
    connect(primaryWindowId: string, componentName: string): Promise<string>;
    read(ownerToken: string): Promise<string>;
    open(ownerToken: string, request: string): Promise<string>;
    move(ownerToken: string, id: string, request: string): Promise<string>;
    focus(ownerToken: string, id: string): Promise<string>;
    minimize(ownerToken: string, id: string): Promise<string>;
    restore(ownerToken: string, id: string): Promise<string>;
    requestClose(ownerToken: string, id: string): Promise<string>;
    resolveClose(ownerToken: string, id: string, generation: string, token: string, accepted: boolean): Promise<string>;
    dispose(ownerToken: string): Promise<void>;
    onSnapshot(listener: (json: string) => void): {
        remove(): void;
    };
    onError(listener: (message: string) => void): {
        remove(): void;
    };
}

export interface WindowsCloseRequest {
    readonly id: string;
    readonly generation: string;
    readonly token: string;
}

export interface WindowsDesktopLayout {
    readonly schema: 1;
    readonly referenceDpi: number;
    readonly layout: LayoutSnapshot;
}

export interface WindowsDesktopSnapshot {
    readonly schema: 1;
    readonly ownerToken: string;
    readonly sequence: number;
    readonly referenceDpi: number;
    readonly windows: readonly WindowsObservedWindow[];
    readonly displays: readonly WindowsObservedDisplay[];
    readonly focusedId: string | null;
    readonly pendingCloses: readonly WindowsCloseRequest[];
}

export interface WindowsObservedDisplay extends DisplayInfo {
    readonly pixelBounds: Rect;
    readonly pixelWorkArea: Rect;
}

export interface WindowsObservedWindow extends WindowRecord {
    readonly generation: string;
    readonly primary: boolean;
    readonly pixelRect: Rect;
    readonly dpi: number;
}

export interface WindowsOpenWindow {
    readonly id: string;
    readonly title: string;
    readonly displayId: string;
    readonly rect: Rect;
}

export interface WindowsWindowHost {
    snapshot(): WindowsDesktopSnapshot;
    refresh(): Promise<WindowsDesktopSnapshot>;
    open(spec: WindowsOpenWindow): Promise<WindowsObservedWindow>;
    move(id: string, target: {
        readonly displayId: string;
        readonly rect: Rect;
    }): Promise<void>;
    focus(id: string): Promise<void>;
    minimize(id: string): Promise<void>;
    restore(id: string): Promise<void>;
    requestClose(id: string): Promise<void>;
    resolveClose(request: WindowsCloseRequest, accepted: boolean): Promise<void>;
    captureLayout(): WindowsDesktopLayout;
    restoreLayout(snapshot: WindowsDesktopLayout): Promise<void>;
    beginDrag(sourceId: string, payload: unknown): Outcome;
    dragOver(token: string, targetId: string | null): Outcome;
    drop(token: string, targetId: string, approve: (offer: DragOffer) => boolean | Promise<boolean>): Promise<Outcome>;
    cancelDrag(token: string): Outcome;
    dispose(): Promise<void>;
}

export interface WindowsWindowHostOptions {
    readonly primaryWindowId: string;
    readonly componentName: string;
    readonly owner: WindowsWindowOwner;
    readonly onCloseRequested: (request: WindowsCloseRequest) => void;
    readonly onError?: (error: Error) => void;
}

export interface WindowsWindowOwner {
    getState(): WindowRegistryState;
    commit(state: WindowRegistryState): void;
}

export interface Rect {
    readonly x: number;
    readonly y: number;
    readonly width: number;
    readonly height: number;
}

export interface DisplayInfo {
    readonly id: string;
    readonly bounds: Rect;
    readonly reserved?: readonly Rect[];
    readonly primary?: boolean;
}

export interface DragOffer {
    readonly sourceId: string;
    readonly targetId: string;
    readonly payload: unknown;
}

export interface LayoutSnapshot {
    readonly version: 1;
    readonly windows: readonly SnapshotWindow[];
    readonly focusedId: string | null;
}

export interface Outcome {
    readonly state: WindowRegistryState;
    readonly ok: boolean;
    readonly reason?: RejectReason;
    readonly token?: string;
    readonly offer?: DragOffer;
    readonly transfer?: DragOffer;
    readonly accepted?: boolean;
    readonly cancelledToken?: string;
}

export interface WindowRecord {
    readonly id: string;
    readonly displayId: string;
    readonly rect: Rect;
    readonly status: WindowStatus;
    readonly home?: WindowHome;
}

export interface WindowRegistryState {
    readonly windows: readonly WindowRecord[];
    readonly focusedId: string | null;
    readonly drag: DragSession | null;
    readonly tokenSeq: number;
}

export type WindowsNativeNavigationEvent = {
    readonly type: "destinationInvoked";
    readonly id: string;
} | {
    readonly type: "paneOpenChanged";
    readonly open: boolean;
} | {
    readonly type: "settingsInvoked";
};

export interface WindowsNativeNavigationTransport {
    setDestinations(items: readonly WindowsDestination[], footerItems: readonly WindowsDestination[]): void;
    setSelectedId(selectedId: string | null): void;
    setPaneMode(mode: WindowsPaneMode): void;
    setPaneOpen(open: boolean): void;
    setPaneTitle(title: string): void;
    setSettingsVisible(enabled: boolean): void;
    subscribe(onEvent: (event: WindowsNativeNavigationEvent) => void): () => void;
}

export interface WindowsNavigationState {
    readonly items: readonly WindowsDestination[];
    readonly footerItems?: readonly WindowsDestination[];
    readonly selectedId: string | null;
    readonly paneMode: WindowsPaneMode;
    readonly paneOpen: boolean;
    readonly paneTitle?: string;
    readonly settingsVisible?: boolean;
}

export interface ViewStyle extends FlexStyle, ShadowStyleIOS, TransformsStyle {
